	/** 
	 * jumpstart the process by instantiating2 Forecast
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		forecastId = ForecastService.getForecastInstance()
		.createForecast( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ForecastService.getForecastInstance()
				.createForecast( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.forecastSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Forecast : " + successValue.getForecastId());
							  if (successValue.getForecastId().equals(forecastId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfForecastList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Forecast test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on forecast consumed")
					);
			subscriber.forecastSubscribe( forecastId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Forecast : " + successValue.getForecastId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfForecastList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on forecast for forecastId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Forecast. 
	 */
	protected Forecast read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Forecast" );

		Forecast entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Forecast with primary key" );
		msg.append( forecastId );
		
		ForecastFetchOneSummary fetchOneSummary = new ForecastFetchOneSummary( forecastId );

		try {
			entity = ForecastService.getForecastInstance().getForecast( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Forecast " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Forecast.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Forecast." );

		StringBuilder msg = new StringBuilder( "Failed to update a Forecast : " );        
		Forecast entity = read();
		UpdateForecastCommand command = generateUpdateCommand();
		command.setForecastId(entity.getForecastId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Forecast." );

			// for use later on...
			forecastId = entity.getForecastId();

			ForecastService proxy = ForecastService.getForecastInstance();  

			proxy.updateForecast( command ).get();

			LOGGER.info( "-- Successfully saved Forecast - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + forecastId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Forecast.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Forecast." );

		Forecast entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Forecast with id " + forecastId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Forecast with id " + forecastId );

			throw e;
		}

		try{
			ForecastService.getForecastInstance().delete( new DeleteForecastCommand( entity.getForecastId() ) ).get();
			LOGGER.info( "-- Successfully deleted Forecast with id " + forecastId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Forecast with id " + forecastId );

			throw e;
		}
	}

	/**
	 * get all Forecasts.
	 */
	protected List<Forecast> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Forecasts:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Forecast : " );        
		List<Forecast> collection  = new ArrayList<>();

		try {
			// call the static get method on the ForecastService
			collection = ForecastService.getForecastInstance().getAllForecast();
			assertNotNull( collection, "An Empty collection of Forecast was incorrectly returned.");
			
			// Now print out the values
			Forecast entity = null;            
			Iterator<Forecast> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getForecastId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

